// `while (w0 < w1)`: mdct_bitreverse verbatim. The same-TU caller is the head of 1.0.1 mdct_backward's call sequence.
#define DATA_TYPE float
#define REG_TYPE float
#define MULT_NORM(x) (x)
#define HALVE(x) ((x)*.5f)

